#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
============================================================
  CHATUR — Aplikasi Chat Real-Time (multi-user)
  + Pesan suara (voice note) real-time
  + Kirim file gambar / video / dokumen
  Backend: Flask + Flask-Socket.IO
  Cara jalankan:
    pip install -r requirements.txt
    python app.py
    Buka http://localhost:5000
============================================================
"""
import time
import base64
import binascii
import os
from collections import defaultdict

from flask import Flask
from flask_socketio import SocketIO, emit, join_room, leave_room

app = Flask(__name__)
app.config["SECRET_KEY"] = os.environ.get("SECRET_KEY", "ganti-ini-dengan-rahasia-chatur")

# Batas ukuran file (setelah base64) — kira-kira ~6 MB file asli.
# Naikkan jika perlu, tapi kirim file besar lewat WebSocket akan lambat.
MAX_FILE_BASE64 = 8_000_000  # ~8 MB base64

try:
    import eventlet  # noqa: F401
    async_mode = "eventlet"
except ImportError:
    async_mode = "threading"

socketio = SocketIO(app, cors_allowed_origins="*", async_mode=async_mode,
                    max_http_buffer_size=MAX_FILE_BASE64 + 2_000_000)

ROOMS = ["umum", "teknis", "santai"]
rooms_users = defaultdict(dict)


INDEX_HTML = '<!DOCTYPE html>\n<html lang="id">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">\n<meta name="theme-color" content="#0d9488">\n<title>CHATUR — Chat Real-Time</title>\n<link rel="icon" href="data:image/png;base64," type="image/png">\n<script src="https://cdn.socket.io/4.7.5/socket.io.min.js"></script>\n<style>\n  :root{\n    --bg:#f4f6f8; --panel:#ffffff; --text:#1a2332; --muted:#7a8699;\n    --accent:#0d9488; --accent-dark:#0f766e; --accent-soft:#ccfbf1;\n    --bubble-me:#0d9488; --bubble-me-text:#ffffff; --bubble-other:#ffffff;\n    --border:#e3e8ee; --system:#8b5cf6; --danger:#dc2626;\n    --shadow:0 4px 20px rgba(15,23,42,.08);\n  }\n  *{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent;}\n  body{font-family:\'Segoe UI\',system-ui,-apple-system,sans-serif;background:var(--bg);color:var(--text);height:100vh;display:flex;align-items:center;justify-content:center;}\n\n  /* ---------- Layar Gabung ---------- */\n  #joinScreen{background:var(--panel);padding:36px 28px;border-radius:20px;box-shadow:var(--shadow);width:100%;max-width:400px;text-align:center;}\n  .logo-img{width:104px;height:104px;border-radius:50%;object-fit:cover;box-shadow:0 8px 30px rgba(13,148,136,.35);border:3px solid #fff;margin-bottom:10px;}\n  .logo{font-size:34px;font-weight:800;letter-spacing:.18em;background:linear-gradient(90deg,#b8860b,#daa520);-webkit-background-clip:text;background-clip:text;color:transparent;margin-bottom:2px;}\n  .logo-mini-img{width:26px;height:26px;border-radius:50%;object-fit:cover;vertical-align:middle;margin-right:4px;border:1px solid var(--border);}\n  .tagline{color:var(--muted);font-size:13px;margin-bottom:26px;}\n  .field{text-align:left;margin-bottom:14px;}\n  .field label{display:block;font-size:13px;font-weight:600;margin-bottom:6px;}\n  .field input,.field select{width:100%;padding:12px 14px;border:1.5px solid var(--border);border-radius:10px;font-size:15px;outline:none;background:#fafbfc;}\n  .field input:focus,.field select:focus{border-color:var(--accent);}\n  #joinBtn{width:100%;padding:13px;border:none;border-radius:10px;background:linear-gradient(90deg,#0d9488,#0891b2);color:#fff;font-size:16px;font-weight:700;cursor:pointer;letter-spacing:.04em;}\n  .err{color:var(--danger);font-size:13px;margin-top:10px;min-height:18px;}\n  .hint{font-size:11.5px;color:var(--muted);margin-top:14px;line-height:1.5;}\n\n  /* ---------- Layar Chat ---------- */\n  #chatScreen{display:none;width:100%;height:100vh;max-width:900px;background:var(--panel);flex-direction:column;box-shadow:var(--shadow);}\n  header{display:flex;align-items:center;justify-content:space-between;padding:12px 18px;border-bottom:1px solid var(--border);}\n  .room-info h2{font-size:16px;display:flex;align-items:center;gap:8px;}\n  .logo-mini{font-weight:800;letter-spacing:.1em;color:var(--accent);font-size:13px;}\n  .dot{width:9px;height:9px;border-radius:50%;background:#22c55e;display:inline-block;}\n  .room-info span{font-size:11.5px;color:var(--muted);display:block;margin-top:2px;}\n  #usersBtn{background:var(--accent-soft);color:var(--accent);border:none;padding:7px 13px;border-radius:999px;font-size:12.5px;font-weight:600;cursor:pointer;}\n  #usersPanel{display:none;padding:10px 18px;border-bottom:1px solid var(--border);background:#fafbfc;flex-wrap:wrap;gap:6px;}\n  .u-chip{background:var(--panel);border:1px solid var(--border);padding:4px 12px;border-radius:999px;font-size:12px;}\n\n  #messages{flex:1;overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:9px;background:linear-gradient(180deg,#f8fafb,#f4f6f8);}\n  .msg{max-width:78%;display:flex;flex-direction:column;}\n  .msg.me{align-self:flex-end;align-items:flex-end;}\n  .msg.other{align-items:flex-start;}\n  .bubble{padding:9px 13px;border-radius:16px;font-size:14.5px;line-height:1.45;word-wrap:break-word;white-space:pre-wrap;box-shadow:0 1px 2px rgba(0,0,0,.05);max-width:100%;}\n  .msg.me .bubble{background:var(--bubble-me);color:var(--bubble-me-text);border-bottom-right-radius:4px;}\n  .msg.other .bubble{background:var(--bubble-other);border:1px solid var(--border);border-bottom-left-radius:4px;}\n  .meta{font-size:11px;color:var(--muted);margin:3px 6px 0;}\n  .msg.me .meta{text-align:right;}\n  .sys{align-self:center;background:rgba(139,92,246,.1);color:var(--system);font-size:12px;padding:5px 14px;border-radius:999px;margin:3px 0;}\n\n  /* preview media dalam bubble */\n  .media{border-radius:12px;overflow:hidden;max-width:260px;}\n  .media img{display:block;width:100%;height:auto;cursor:zoom-in;}\n  .media video,.media audio{display:block;width:100%;max-width:260px;outline:none;}\n  .voice-note{display:flex;align-items:center;gap:8px;padding:8px 12px;border-radius:14px;min-width:180px;}\n  .voice-note audio{flex:1;height:36px;}\n  .voice-label{font-size:11px;opacity:.85;white-space:nowrap;}\n  .file-link{display:inline-flex;align-items:center;gap:8px;padding:10px 14px;border-radius:12px;text-decoration:none;font-size:13.5px;font-weight:600;}\n  .msg.me .file-link{color:#fff;background:rgba(255,255,255,.18);}\n  .msg.other .file-link{color:var(--accent-dark);background:var(--accent-soft);}\n\n  #typing{height:18px;padding:0 18px;font-size:12px;color:var(--muted);font-style:italic;}\n\n  /* area input + kontrol */\n  #toolbar{display:flex;gap:8px;align-items:center;padding:10px 14px;border-top:1px solid var(--border);background:var(--panel);flex-wrap:nowrap;}\n  .ctrl-btn{flex:none;width:42px;height:42px;border-radius:50%;border:1.5px solid var(--border);background:var(--panel);cursor:pointer;font-size:18px;display:flex;align-items:center;justify-content:center;transition:all .15s;}\n  .ctrl-btn:hover{border-color:var(--accent);color:var(--accent);}\n  .ctrl-btn.recording{background:var(--danger);border-color:var(--danger);color:#fff;animation:pulse 1s infinite;}\n  @keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(220,38,38,.5);}50%{box-shadow:0 0 0 8px rgba(220,38,38,0);}}\n  #input{flex:1;padding:12px 16px;border:1.5px solid var(--border);border-radius:999px;font-size:15px;outline:none;min-width:0;}\n  #input:focus{border-color:var(--accent);}\n  #sendBtn{flex:none;padding:0 20px;height:42px;border:none;border-radius:999px;background:var(--accent);color:#fff;font-size:15px;font-weight:600;cursor:pointer;}\n  #recIndicator{display:none;align-items:center;gap:8px;padding:6px 14px;font-size:12.5px;color:var(--danger);font-weight:600;}\n  #recTimer{font-variant-numeric:tabular-nums;}\n  #fileInput{display:none;}\n  #connStatus{font-size:11px;color:var(--muted);}\n  #installBtn{display:none;background:var(--accent-soft);color:var(--accent);border:none;padding:6px 12px;border-radius:999px;font-size:11.5px;font-weight:600;cursor:pointer;margin-top:8px;}\n  @media (max-width:600px){\n    #chatScreen{max-width:100%;}\n    .msg{max-width:86%;}\n    .media{max-width:200px;}\n  }\n</style>\n</head>\n<body>\n\n<!-- LAYAR GABUNG -->\n<div id="joinScreen">\n  <img src="data:image/png;base64," alt="Logo CHATUR" class="logo-img">\n  <div class="logo">CHATUR</div>\n  <div class="tagline">Chat · Suara · Gambar · Video — real-time</div>\n  <div class="field">\n    <label for="username">Nama panggilan</label>\n    <input type="text" id="username" maxlength="24" placeholder="Contoh: Budi" autocomplete="off">\n  </div>\n  <div class="field">\n    <label for="room">Ruangan</label>\n    <select id="room">\n      <option value="umum">Umum</option><option value="teknis">Teknis</option><option value="santai">Santai</option>\n    </select>\n  </div>\n  <button id="joinBtn">Gabung Chat</button>\n  <button id="installBtn">⬇ Install Aplikasi (Android)</button>\n  <div class="err" id="joinErr"></div>\n  <div class="hint">Kirim teks, rekam pesan suara (tombol merah), dan lampirkan gambar/video/dokumen. Buka di HP untuk pengalaman mobile.</div>\n</div>\n\n<!-- LAYAR CHAT -->\n<div id="chatScreen">\n  <header>\n    <div class="room-info">\n      <h2><span class="dot"></span><span id="roomName">Umum</span> <img src="data:image/png;base64," class="logo-mini-img" alt=""><span class="logo-mini">CHATUR</span></h2>\n      <span id="connStatus">Menghubungkan...</span>\n    </div>\n    <button id="usersBtn">Online: <span id="onlineCount">0</span></button>\n  </header>\n  <div id="usersPanel"></div>\n  <div id="messages"></div>\n  <div id="typing"></div>\n  <div id="recIndicator"><span style="width:10px;height:10px;border-radius:50%;background:#dc2626;display:inline-block;animation:pulse 1s infinite;"></span> Merekam suara... <span id="recTimer">0:00</span> — ketuk tombol merah untuk berhenti &amp; kirim</div>\n  <form id="toolbar" autocomplete="off">\n    <button type="button" class="ctrl-btn" id="attachBtn" title="Lampirkan file">📎</button>\n    <input type="file" id="fileInput" accept="image/*,video/*,audio/*,.pdf,.doc,.docx,.txt,.zip,.rar">\n    <input type="text" id="input" placeholder="Ketik pesan..." maxlength="2000" autocomplete="off">\n    <button type="button" class="ctrl-btn" id="recBtn" title="Rekam pesan suara">🎤</button>\n    <button type="submit" id="sendBtn">Kirim</button>\n  </form>\n</div>\n\n<script>\n(function(){\n  var socket = io();\n  var myName = \'\', currentRoom = \'\';\n  var MAX_FILE = 6*1024*1024; // ~6 MB\n\n  var joinScreen=document.getElementById(\'joinScreen\');\n  var chatScreen=document.getElementById(\'chatScreen\');\n  var messagesEl=document.getElementById(\'messages\');\n  var usersPanel=document.getElementById(\'usersPanel\');\n  var typingEl=document.getElementById(\'typing\');\n  var input=document.getElementById(\'input\');\n  var toolbar=document.getElementById(\'toolbar\');\n  var fileInput=document.getElementById(\'fileInput\');\n  var recBtn=document.getElementById(\'recBtn\');\n  var recIndicator=document.getElementById(\'recIndicator\');\n  var recTimer=document.getElementById(\'recTimer\');\n\n  var mediaRecorder=null, recChunks=[], recStart=0, recInterval=null;\n\n  function fmtTime(ts){var d=new Date(ts*1000);return (\'0\'+d.getHours()).slice(-2)+\':\'+(\'0\'+d.getMinutes()).slice(-2);}\n  function fmtDur(sec){var m=Math.floor(sec/60),s=Math.floor(sec%60);return m+\':\'+(\'0\'+s).slice(-2);}\n  function scrollBottom(){messagesEl.scrollTop=messagesEl.scrollHeight;}\n  function dataUrlOf(mime,b64){return \'data:\'+mime+\';base64,\'+b64;}\n\n  socket.on(\'connect\',function(){document.getElementById(\'connStatus\').textContent=\'Terhubung\';});\n  socket.on(\'disconnect\',function(){document.getElementById(\'connStatus\').textContent=\'Terputus — menyambung ulang...\';});\n\n  // ---------- Gabung ----------\n  document.getElementById(\'joinBtn\').addEventListener(\'click\',join);\n  document.getElementById(\'username\').addEventListener(\'keydown\',function(e){if(e.key===\'Enter\')join();});\n  function join(){\n    var name=document.getElementById(\'username\').value.trim();\n    var room=document.getElementById(\'room\').value;\n    if(!name){document.getElementById(\'joinErr\').textContent=\'Nama panggilan wajib diisi.\';return;}\n    myName=name;currentRoom=room;\n    socket.emit(\'join\',{username:name,room:room});\n    joinScreen.style.display=\'none\';\n    chatScreen.style.display=\'flex\';\n    document.getElementById(\'roomName\').textContent=room.charAt(0).toUpperCase()+room.slice(1);\n    input.focus();\n  }\n\n  // ---------- Render pesan teks ----------\n  function appendText(data){\n    if(data.system){\n      var d=document.createElement(\'div\');d.className=\'sys\';\n      d.textContent=data.msg+\' · \'+fmtTime(data.ts);\n      messagesEl.appendChild(d);\n    }else{\n      var mine=(data.username===myName);\n      var wrap=document.createElement(\'div\');wrap.className=\'msg \'+(mine?\'me\':\'other\');\n      var b=document.createElement(\'div\');b.className=\'bubble\';b.textContent=data.msg;\n      var m=document.createElement(\'div\');m.className=\'meta\';\n      m.textContent=(mine?\'Anda\':data.username)+\' · \'+fmtTime(data.ts);\n      wrap.appendChild(b);wrap.appendChild(m);messagesEl.appendChild(wrap);\n    }\n    scrollBottom();\n  }\n  socket.on(\'message\',appendText);\n\n  // ---------- Render pesan file (gambar/video/audio/dokumen/voice) ----------\n  socket.on(\'file\',function(data){\n    var mine=(data.username===myName);\n    var wrap=document.createElement(\'div\');wrap.className=\'msg \'+(mine?\'me\':\'other\');\n    var bubble=document.createElement(\'div\');bubble.className=\'bubble\';\n    var mime=data.mimetype||\'\';\n    var url=dataUrlOf(mime,data.data);\n\n    if(data.voice || mime.indexOf(\'audio\')===0){\n      var vn=document.createElement(\'div\');vn.className=\'voice-note\';\n      if(mine){vn.style.background=\'rgba(255,255,255,.18)\';}else{vn.style.background=\'var(--accent-soft)\';}\n      var au=document.createElement(\'audio\');au.controls=true;au.src=url;\n      var lbl=document.createElement(\'span\');lbl.className=\'voice-label\';lbl.textContent=(data.voice?\'🎙 Pesan suara\':\'🔊 Audio\')+\' · \'+data.filename;\n      if(mine){lbl.style.color=\'#fff\';}else{lbl.style.color=\'var(--accent-dark)\';}\n      vn.appendChild(au);vn.appendChild(lbl);bubble.appendChild(vn);\n    }else if(mime.indexOf(\'image\')===0){\n      var md=document.createElement(\'div\');md.className=\'media\';\n      var im=document.createElement(\'img\');im.src=url;im.alt=data.filename;\n      im.addEventListener(\'click\',function(){window.open(url,\'_blank\');});\n      md.appendChild(im);bubble.appendChild(md);\n    }else if(mime.indexOf(\'video\')===0){\n      var mdv=document.createElement(\'div\');mdv.className=\'media\';\n      var vd=document.createElement(\'video\');vd.controls=true;vd.src=url;vd.preload=\'metadata\';\n      mdv.appendChild(vd);bubble.appendChild(mdv);\n    }else{\n      var a=document.createElement(\'a\');a.className=\'file-link\';a.href=url;a.download=data.filename;\n      a.innerHTML=\'📄 \'+data.filename+\' <span style="font-weight:400;opacity:.75">(unduh)</span>\';\n      bubble.appendChild(a);\n    }\n    var m=document.createElement(\'div\');m.className=\'meta\';\n    m.textContent=(mine?\'Anda\':data.username)+\' · \'+fmtTime(data.ts);\n    wrap.appendChild(bubble);wrap.appendChild(m);\n    messagesEl.appendChild(wrap);\n    scrollBottom();\n  });\n\n  // ---------- User online ----------\n  socket.on(\'users\',function(data){\n    document.getElementById(\'onlineCount\').textContent=data.users.length;\n    usersPanel.innerHTML=\'\';\n    data.users.forEach(function(u){var c=document.createElement(\'span\');c.className=\'u-chip\';c.textContent=u;usersPanel.appendChild(c);});\n  });\n  document.getElementById(\'usersBtn\').addEventListener(\'click\',function(){\n    usersPanel.style.display=(usersPanel.style.display===\'flex\')?\'none\':\'flex\';\n  });\n\n  // ---------- Typing indicator ----------\n  var typingUsers={};\n  socket.on(\'typing\',function(data){typingUsers[data.username]=Date.now();renderTyping();setTimeout(renderTyping,1500);});\n  function renderTyping(){\n    var now=Date.now(),names=[];\n    for(var n in typingUsers){if(now-typingUsers[n]<1400)names.push(n);else delete typingUsers[n];}\n    typingEl.textContent=names.length===0?\'\':(names.length===1?names[0]+\' sedang mengetik...\':names.join(\', \')+\' sedang mengetik...\');\n  }\n  input.addEventListener(\'input\',function(){socket.emit(\'typing\',{room:currentRoom});});\n\n  // ---------- Kirim teks ----------\n  toolbar.addEventListener(\'submit\',function(e){\n    e.preventDefault();\n    var txt=input.value.trim();\n    if(!txt)return;\n    socket.emit(\'message\',{room:currentRoom,msg:txt});\n    input.value=\'\';\n  });\n\n  // ---------- Kirim file (gambar/video/dokumen) ----------\n  document.getElementById(\'attachBtn\').addEventListener(\'click\',function(){fileInput.click();});\n  fileInput.addEventListener(\'change\',function(){\n    var f=fileInput.files[0];\n    if(!f)return;\n    if(f.size>MAX_FILE){alert(\'File terlalu besar. Maks 6 MB.\');fileInput.value=\'\';return;}\n    var reader=new FileReader();\n    reader.onload=function(){\n      var b64=reader.result.split(\',\')[1];\n      socket.emit(\'file\',{room:currentRoom,filename:f.name,mimetype:f.type||\'application/octet-stream\',data:b64,voice:false});\n    };\n    reader.readAsDataURL(f);\n    fileInput.value=\'\';\n  });\n\n  // ---------- Rekam & kirim pesan suara ----------\n  recBtn.addEventListener(\'click\',function(){\n    if(mediaRecorder && mediaRecorder.state===\'recording\'){\n      mediaRecorder.stop();\n      return;\n    }\n    if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia){\n      alert(\'Browser tidak mendukung perekaman suara.\');return;\n    }\n    navigator.mediaDevices.getUserMedia({audio:true}).then(function(stream){\n      recChunks=[];\n      var opts={mimeType:\'audio/webm\'};\n      try{mediaRecorder=new MediaRecorder(stream,opts);}catch(e){mediaRecorder=new MediaRecorder(stream);}\n      mediaRecorder.ondataavailable=function(e){if(e.data.size>0)recChunks.push(e.data);};\n      mediaRecorder.onstop=function(){\n        stream.getTracks().forEach(function(t){t.stop();});\n        var blob=new Blob(recChunks,{type:\'audio/webm\'});\n        if(blob.size>MAX_FILE){alert(\'Rekaman terlalu panjang. Maks 6 MB.\');resetRec();return;}\n        var reader=new FileReader();\n        reader.onload=function(){\n          var b64=reader.result.split(\',\')[1];\n          socket.emit(\'file\',{room:currentRoom,filename:\'pesan-suara.webm\',mimetype:\'audio/webm\',data:b64,voice:true});\n        };\n        reader.readAsDataURL(blob);\n        resetRec();\n      };\n      mediaRecorder.start();\n      recStart=Date.now();\n      recBtn.classList.add(\'recording\');\n      recIndicator.style.display=\'flex\';\n      recInterval=setInterval(function(){recTimer.textContent=fmtDur((Date.now()-recStart)/1000);},500);\n    }).catch(function(){\n      alert(\'Izin mikrofon ditolak. Aktifkan izin mikrofon untuk merekam suara.\');\n    });\n  });\n  function resetRec(){\n    recBtn.classList.remove(\'recording\');\n    recIndicator.style.display=\'none\';\n    if(recInterval){clearInterval(recInterval);recInterval=null;}\n    recTimer.textContent=\'0:00\';\n    mediaRecorder=null;recChunks=[];\n  }\n\n  // ---------- PWA: tombol install (Android) ----------\n  var deferredPrompt=null;\n  window.addEventListener(\'beforeinstallprompt\',function(e){\n    e.preventDefault();deferredPrompt=e;\n    document.getElementById(\'installBtn\').style.display=\'inline-block\';\n  });\n  document.getElementById(\'installBtn\').addEventListener(\'click\',function(){\n    if(!deferredPrompt)return;\n    deferredPrompt.prompt();\n    deferredPrompt.userChoice.then(function(){deferredPrompt=null;});\n    document.getElementById(\'installBtn\').style.display=\'none\';\n  });\n  if(\'serviceWorker\' in navigator){\n    window.addEventListener(\'load\',function(){navigator.serviceWorker.register(\'/static/sw.js\').catch(function(){});});\n  }\n})();\n</script>\n</body>\n</html>\n'

@app.route("/")
def index():
    return INDEX_HTML


def _current_room_of(sid):
    for room, users in rooms_users.items():
        if sid in users:
            return room, users[sid]
    return None, None


@socketio.on("join")
def on_join(data):
    username = str(data.get("username", "")).strip()[:24]
    room = str(data.get("room", "umum")).strip()
    if not username or room not in ROOMS:
        return
    for r, users in list(rooms_users.items()):
        if request.sid in users and r != room:
            old_name = users.pop(request.sid)
            leave_room(r)
            emit("message", {"username": "Sistem",
                             "msg": f"{old_name} pindah ke ruang {room}",
                             "ts": time.time(), "system": True}, room=r)
            emit("users", {"users": list(users.values())}, room=r)

    join_room(room)
    rooms_users[room][request.sid] = username
    emit("message", {"username": "Sistem",
                     "msg": f"{username} bergabung ke ruang {room}",
                     "ts": time.time(), "system": True}, room=room)
    emit("users", {"users": list(rooms_users[room].values())}, room=room)


@socketio.on("message")
def on_message(data):
    room = str(data.get("room", "umum")).strip()
    username = rooms_users.get(room, {}).get(request.sid)
    if not username:
        return
    msg = str(data.get("msg", "")).strip()[:2000]
    if not msg:
        return
    emit("message", {"username": username, "msg": msg,
                     "ts": time.time(), "system": False}, room=room)


@socketio.on("file")
def on_file(data):
    """Menerima file (gambar/video/audio/dokumen) dalam bentuk base64 lalu broadcast."""
    room, username = _current_room_of(request.sid)
    if not username:
        return
    filename = str(data.get("filename", "file")).strip()[:120] or "file"
    mimetype = str(data.get("mimetype", "application/octet-stream"))[:80]
    b64 = str(data.get("data", ""))

    if len(b64) > MAX_FILE_BASE64:
        emit("message", {"username": "Sistem",
                         "msg": f"Gagal mengirim {filename}: ukuran terlalu besar (maks ~6 MB).",
                         "ts": time.time(), "system": True})
        return
    # Validasi base64 (hindari data rusak)
    try:
        base64.b64decode(b64.split(",")[-1], validate=True)
    except (binascii.Error, ValueError):
        emit("message", {"username": "Sistem",
                         "msg": f"Gagal mengirim {filename}: data file tidak valid.",
                         "ts": time.time(), "system": True})
        return

    is_voice = bool(data.get("voice", False))
    emit("file", {"username": username, "filename": filename,
                  "mimetype": mimetype, "data": b64, "voice": is_voice,
                  "ts": time.time()}, room=room)


@socketio.on("typing")
def on_typing(data):
    room = str(data.get("room", "umum")).strip()
    username = rooms_users.get(room, {}).get(request.sid)
    if username:
        emit("typing", {"username": username}, room=room, include_self=False)


@socketio.on("disconnect")
def on_disconnect():
    for room, users in list(rooms_users.items()):
        if request.sid in users:
            username = users.pop(request.sid)
            leave_room(room)
            emit("message", {"username": "Sistem",
                             "msg": f"{username} meninggalkan ruang {room}",
                             "ts": time.time(), "system": True}, room=room)
            emit("users", {"users": list(users.values())}, room=room)


if __name__ == "__main__":
    port = int(os.environ.get("PORT", 5000))
    socketio.run(app, host="0.0.0.0", port=port, debug=False)
